import type { ChatStreamEventContext } from '../../../types/chat'

import { toRaw } from 'vue'

function toStructuredCloneSafe<T>(value: T): T {
  const rawValue = toRaw(value)

  try {
    return structuredClone(rawValue)
  }
  catch {
    return JSON.parse(JSON.stringify(rawValue)) as T
  }
}

export function normalizeContextSnapshot<
  C extends Pick<ChatStreamEventContext, 'contexts' | 'message'>
  & Partial<Pick<ChatStreamEventContext, 'composedMessage' | 'input'>>,
>(contexts: C): C {
  return {
    ...toStructuredCloneSafe(contexts),
    message: toStructuredCloneSafe(contexts.message),
    composedMessage: contexts.composedMessage ? toStructuredCloneSafe(contexts.composedMessage) : contexts.composedMessage,
    input: contexts.input ? toStructuredCloneSafe(contexts.input) : contexts.input,
    contexts: Object.fromEntries(
      Object
        .entries(toRaw(contexts.contexts))
        .map(([key, ctx]) => [
          key,
          ctx.map(c => toStructuredCloneSafe(c)),
        ]),
    ),
  }
}
